def transform(grid):
    # The pattern is shown twice in separate horizontal bands. The second copy
    # is incomplete; mark the cells present in the first copy but absent there.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rows = [any(v != bg for v in row) for row in grid]
    bands = []
    i = 0
    while i < h:
        if not rows[i]:
            i += 1
            continue
        a = i
        while i < h and rows[i]:
            i += 1
        bands.append((a, i))
    out = [row[:] for row in grid]
    if len(bands) >= 2:
        (a, b), (c, d) = bands[0], bands[1]
        if b-a == d-c:
            for k in range(b-a):
                for x in range(w):
                    if grid[a+k][x] != bg and grid[c+k][x] == bg:
                        out[c+k][x] = 1
    return out

